  <a class="skip-link" href="#main-content">Skip to main content</a>
  <main id="main-content">
    <div class="page-shell">
      <section class="hero" aria-labelledby="support-heading">
        <div>
          <div class="eyebrow">Support</div>
          <h1 id="support-heading">Contact our support team</h1>
          <p>Send us your details and we will follow up with the right person as soon as possible.</p>
        </div>

        <div class="support-notes" aria-label="What to expect">
          <div class="support-note">
            <div class="note-icon" aria-hidden="true">1</div>
            <div>
              <strong>Fast response</strong>
              We use your email to reply and keep you updated.
            </div>
          </div>
          <div class="support-note">
            <div class="note-icon" aria-hidden="true">2</div>
            <div>
              <strong>Optional phone follow-up</strong>
              Add a number only if you want a callback.
            </div>
          </div>
        </div>
      </section>

      <section class="panel" aria-labelledby="form-heading">
        <form id="support-form" novalidate>
          <h2 id="form-heading" style="margin: 0 0 0.25rem; font-size: 1.5rem;">Send a message</h2>

          <div class="form-field">
            <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
            <input id="full-name" name="fullName" type="text" autocomplete="name" required aria-describedby="full-name-error" aria-invalid="false">
            <p class="error-text" id="full-name-error" aria-live="polite"></p>
          </div>

          <div class="form-field">
            <label for="email-address">Email address <span class="required" aria-hidden="true">*</span></label>
            <input id="email-address" name="email" type="email" autocomplete="email" required aria-describedby="email-error" aria-invalid="false">
            <p class="error-text" id="email-error" aria-live="polite"></p>
          </div>

          <div class="form-field">
            <label for="phone-number">Phone number</label>
            <input id="phone-number" name="phone" type="tel" autocomplete="tel" inputmode="tel" aria-describedby="phone-help phone-error" aria-invalid="false">
            <p class="help-text" id="phone-help">Optional. Use a format like +1 555 123 4567 or (555) 123-4567.</p>
            <p class="error-text" id="phone-error" aria-live="polite"></p>
          </div>

          <div class="actions">
            <button type="submit">Send message</button>
            <div class="status" id="form-status" aria-live="polite"></div>
          </div>
        </form>
      </section>
    </div>
  </main>

  <script>
    (() => {
      const form = document.getElementById('support-form');
      const status = document.getElementById('form-status');
      const fields = {
        fullName: {
          input: document.getElementById('full-name'),
          error: document.getElementById('full-name-error'),
          validate(value) {
            if (!value.trim()) {
              return 'Error: Enter your full name.';
            }
            if (value.trim().length < 2) {
              return 'Error: Enter your full name.';
            }
            return '';
          }
        },
        email: {
          input: document.getElementById('email-address'),
          error: document.getElementById('email-error'),
          validate(value) {
            if (!value.trim()) {
              return 'Error: Enter your email address.';
            }
            if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())) {
              return 'Error: Enter a valid email address like name@example.com.';
            }
            return '';
          }
        },
        phone: {
          input: document.getElementById('phone-number'),
          error: document.getElementById('phone-error'),
          validate(value) {
            const trimmed = value.trim();
            if (!trimmed) {
              return '';
            }
            const digits = trimmed.replace(/\D/g, '');
            const validCharacters = /^[0-9+\-() .]+$/.test(trimmed);
            if (!validCharacters || digits.length < 7) {
              return 'Error: Enter a phone number like +1 555 123 4567.';
            }
            return '';
          }
        }
      };

      const setFieldState = (field, message) => {
        field.error.textContent = message;
        field.input.setAttribute('aria-invalid', message ? 'true' : 'false');
      };

      const validateField = (field) => {
        const message = field.validate(field.input.value);
        setFieldState(field, message);
        return !message;
      };

      const validateForm = () => {
        status.textContent = '';
        let firstInvalid = null;

        for (const field of Object.values(fields)) {
          const valid = validateField(field);
          if (!valid && !firstInvalid) {
            firstInvalid = field.input;
          }
        }

        if (firstInvalid) {
          firstInvalid.focus();
          return false;
        }

        return true;
      };

      for (const field of Object.values(fields)) {
        field.input.addEventListener('blur', () => validateField(field));
        field.input.addEventListener('input', () => {
          if (field.error.textContent) {
            validateField(field);
          }
        });
      }

      form.addEventListener('submit', (event) => {
        event.preventDefault();
        if (!validateForm()) {
          return;
        }

        status.textContent = 'Thanks — your message is ready to send.';
        form.reset();
        for (const field of Object.values(fields)) {
          setFieldState(field, '');
        }
        fields.fullName.input.focus();
      });
    })();
  </script>
</body>
